import{_ as a,C as r,o as n,c as s,a2 as e,E as i}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/export-panel.webp",f=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export.md","filePath":"guide/export.md","lastUpdated":1792685126000}'),d={name:"guide/export.md"};function l(g,t,p,u,c,m){const o=r("Clip");return n(),s("div",null,[t[0]||(t[0]=e('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Export writes your story out as one file you can send: a manuscript in standard format for an agent or an editor, an e-book, a screenplay in Fountain, or the whole text as one Markdown file. The export reads the prose from your own files as they are, so what leaves is exactly what you wrote. Leathercase writes the exported file only where you tell it to, and never touches your chapters.</p><p><img src="'+h+'" alt="Settings › Export for The Lamp at Ferrol: the rows File, Font, Paper, Chapters, Chapter headings, Parts, Scene break, Running header, Byline and Word count, with the title page drawn on the right" width="1077" height="1100" loading="lazy"></p><h2 id="two-ways-in" tabindex="-1">Two ways in <a class="header-anchor" href="#two-ways-in" aria-label="Permalink to &quot;Two ways in&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Set up how the story exports, and export</td><td>Open <strong>Settings</strong> (<code>Ctrl+,</code>, or <code>Cmd+,</code> on macOS), pick the story in the <strong>Story</strong> list on the left, then <strong>Export</strong>. The page is titled with the story&#39;s name, such as <strong>The Lamp at Ferrol · Export</strong>.</td></tr><tr><td>Export at once, with the settings already saved</td><td>Press <code>Ctrl/Cmd+E</code> with the story open, or pick <strong>Export the manuscript as one file</strong> from the story&#39;s <code>⋯</code> menu in the sidebar, from the story&#39;s menu in the breadcrumb, or from the command palette.</td></tr></tbody></table><p>Either way Leathercase asks where to save, in your system&#39;s save dialog titled <strong>Export the manuscript</strong>, with a file name already filled in (see <a href="#the-file-s-name">The file&#39;s name</a>). Cancel the dialog and nothing is written. A story never set up exports as a Word manuscript in standard format.</p><h2 id="the-export-page" tabindex="-1">The Export page <a class="header-anchor" href="#the-export-page" aria-label="Permalink to &quot;The Export page&quot;">​</a></h2><p>The page opens with: &quot;Standard manuscript format by default. The export reads the prose from the source, so what leaves is exactly what you wrote.&quot; Its rows depend on the file you choose; each change is saved at once to the story&#39;s <code>suite/Export.json</code>, the path shown at the top right.</p><p>When the story has broken anchors, a line warns you, such as <strong>2 broken anchors. Export ignores anchors, but you may want to look first.</strong> It is only a warning: nothing ever blocks an export.</p><h3 id="file" tabindex="-1">File <a class="header-anchor" href="#file" aria-label="Permalink to &quot;File&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Choice</th><th>What you get</th></tr></thead><tbody><tr><td><strong>Word (.docx)</strong></td><td>Standard manuscript format.</td></tr><tr><td><strong>PDF</strong></td><td>Standard manuscript format.</td></tr><tr><td><strong>E-book (EPUB)</strong></td><td>&quot;An e-book with a title page, a table of contents and a file per chapter.&quot;</td></tr><tr><td><strong>Fountain, the script as written</strong></td><td>&quot;A screenplay&#39;s own Fountain files, exactly as written, joined in order. Only for a story written in Fountain.&quot;</td></tr><tr><td><strong>Markdown, one file</strong></td><td>&quot;The whole text as one markdown file, for Pandoc or a reader.&quot;</td></tr></tbody></table><p>The button at the foot of the page follows the choice: <strong>Export .docx</strong>, <strong>Export PDF</strong>, <strong>Export EPUB</strong>, <strong>Export .fountain</strong> or <strong>Export .md</strong>.</p><h3 id="rows-for-a-manuscript-in-standard-format" tabindex="-1">Rows for a manuscript in standard format <a class="header-anchor" href="#rows-for-a-manuscript-in-standard-format" aria-label="Permalink to &quot;Rows for a manuscript in standard format&quot;">​</a></h3><p>Word and PDF follow standard manuscript format as agents and editors ask for it: a title page, then the text double-spaced in a 12-point face with one-inch margins, every paragraph indented, each chapter on a new page a third of the way down, <code>#</code> between scenes, a running header, and END after the last line.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it sets</th></tr></thead><tbody><tr><td><strong>Font</strong></td><td><strong>Courier</strong> or <strong>Times New Roman</strong>. &quot;12 pt, double-spaced, 1 in margins.&quot;</td></tr><tr><td><strong>Paper</strong></td><td><strong>Letter</strong> or <strong>A4</strong>. &quot;Letter for American agents and editors, A4 elsewhere.&quot;</td></tr><tr><td><strong>Chapters</strong></td><td><strong>Each note; its headings are scene breaks</strong>, or <strong>Each innermost folder; its notes are scenes</strong>. &quot;Each starts on a new page, a third of the way down.&quot;</td></tr><tr><td><strong>Chapter headings</strong></td><td><strong>Chapter One, then the title</strong>, <strong>Chapter One</strong>, or <strong>The title</strong>. &quot;How a chapter is headed on its first page.&quot;</td></tr><tr><td><strong>Parts</strong></td><td>On or off. &quot;Folders above the chapters print as a page of their own.&quot;</td></tr><tr><td><strong>Scene break</strong></td><td>Shown, not set: <code>#</code> in a manuscript. &quot;Headings inside a chapter and horizontal rules.&quot;</td></tr><tr><td><strong>Running header</strong></td><td>The header keyword. &quot;Surname / KEYWORD / page, on every page but the title page.&quot; Left empty, the keyword is the title without a leading article, in capitals: <code>LAMP AT FERROL</code>.</td></tr><tr><td><strong>Byline</strong></td><td>The pen name the story is published under (see below).</td></tr><tr><td><strong>Word count</strong></td><td>The story&#39;s words, rounded, as the title page prints them. &quot;Rounded on the title page.&quot; Shows <strong>not read yet</strong> until the story has been read.</td></tr></tbody></table><p>Beside the rows, the <strong>Title page</strong> is drawn from what the export will print: your name and contact top left (or <strong>Your name and contact</strong> when Home › Author is empty), the rounded word count top right (&quot;about 5,000 words&quot;), and the title in capitals halfway down, with <strong>by</strong> and the byline under it once the story has a pen name (<strong>Byline</strong> reads <strong>Add your name…</strong> until then). The caption under it says what follows, here for a pen name of Vidal: &quot;Title page · then Vidal / LAMP AT FERROL / 2 at the top of every page. Legal name and contact come from Home › Author; the pen name comes from the story.&quot; Without a surname the running header starts at the keyword (<strong>LAMP AT FERROL / 2</strong>); with neither, it is the page number alone.</p>',16)),i(o,{name:"export-panel-change",caption:"Switching File from Word to E-book, then to Markdown, and back: the rows for a manuscript come and go, and the title page follows"}),t[1]||(t[1]=e('<h3 id="rows-for-an-e-book" tabindex="-1">Rows for an e-book <a class="header-anchor" href="#rows-for-an-e-book" aria-label="Permalink to &quot;Rows for an e-book&quot;">​</a></h3><p>An EPUB has <strong>Chapters</strong>, <strong>Chapter headings</strong>, <strong>Parts</strong>, <strong>Scene break</strong> and <strong>Byline</strong>, as above, with these differences: each chapter is a file of its own in the book, listed in its contents (&quot;Each is a file of its own in the book, listed in its contents.&quot;), and a scene break is an ornament, <code>* * *</code>, rather than <code>#</code>. The book has a title page, a table of contents, and your italics and bold. The same title and byline always export as the same book, so an e-reader treats a new export as a new version rather than a new title.</p><h3 id="fountain-and-markdown" tabindex="-1">Fountain and Markdown <a class="header-anchor" href="#fountain-and-markdown" aria-label="Permalink to &quot;Fountain and Markdown&quot;">​</a></h3><p>These two have no layout rows:</p><ul><li><strong>Fountain</strong> gives the script&#39;s own <code>.fountain</code> files back exactly as they are, in the manuscript&#39;s order. One file comes back byte for byte; several are joined with a page break (<code>===</code>), and only the first keeps its title page. A story with no Fountain file cannot export as Fountain, and Leathercase says so: <strong>This story has no Fountain files: the Fountain export gives a script back as it was written. Choose another format for it in Settings › Export.</strong></li><li><strong>Markdown, one file</strong> writes the manuscript page as one Markdown document: the same headings and prose the <a href="/guide/guide/manuscript">manuscript</a> view shows, with front matter naming what it is. Your <code>%% comments %%</code> stay behind; highlights are part of the text and go along.</li></ul><h3 id="the-byline-and-your-contact-details" tabindex="-1">The byline and your contact details <a class="header-anchor" href="#the-byline-and-your-contact-details" aria-label="Permalink to &quot;The byline and your contact details&quot;">​</a></h3><p>The title page takes its contact block from <strong>Settings › Author</strong> (the home&#39;s section, shown on the Export page as Home › Author): your <strong>Legal name</strong>, <strong>Address</strong>, <strong>Email</strong> and <strong>Phone</strong>, or your agent&#39;s details, which replace yours when set. Contact details stay in the home and only appear in exports.</p><p>The byline is a pen name:</p><ul><li>With no pen name yet, the <strong>Byline</strong> row is a link, <strong>Add your name…</strong> (or your legal name), which takes you to the Author section. Stories are published under your legal name until you add one.</li><li>With pen names, the row is a list: the default pen name, marked <strong>· default</strong>, then the others. The choice is kept with the story.</li></ul><p>The running header takes the last word of the pen name as the surname; change it beside the name in the Author section.</p><h2 id="the-book-s-own-words" tabindex="-1">The book&#39;s own words <a class="header-anchor" href="#the-book-s-own-words" aria-label="Permalink to &quot;The book&#39;s own words&quot;">​</a></h2><p>The words the layout adds, such as <strong>Chapter One</strong>, <strong>Contents</strong>, <strong>by</strong>, <strong>about 5,000 words</strong>, <strong>Scene break</strong> and <strong>END</strong>, are the book&#39;s, not the app&#39;s. They follow the story&#39;s language, set under <strong>Language</strong> in the story&#39;s settings (see <a href="/guide/guide/story-settings#prose">Story settings</a>), even when the app is in another language. The page says so: &quot;The book&#39;s own words, from Chapter One to the contents, follow the story&#39;s language, set in Story settings.&quot; A story in Portuguese exports with &quot;Capítulo Um&quot; and &quot;Sumário&quot; from an app set to English.</p><p>When the story&#39;s language is not set, Leathercase tells it from the prose, and uses English until there is enough to tell. The title page drawn on the Export page uses the same language.</p><h2 id="the-file-s-name" tabindex="-1">The file&#39;s name <a class="header-anchor" href="#the-file-s-name" aria-label="Permalink to &quot;The file&#39;s name&quot;">​</a></h2><p>The save dialog offers a name from the story&#39;s name, with any character a file system refuses taken out:</p><table tabindex="0"><thead><tr><th>File</th><th>Offered name</th></tr></thead><tbody><tr><td>Word, PDF, EPUB, Fountain</td><td><code>The Lamp at Ferrol.docx</code>, <code>.pdf</code>, <code>.epub</code>, <code>.fountain</code></td></tr><tr><td>Markdown</td><td><code>The Lamp at Ferrol (manuscript).md</code></td></tr></tbody></table><p>The word &quot;manuscript&quot; in the Markdown name, and the fallback name &quot;Manuscript&quot; when nothing of the title is left, are in the story&#39;s language too. You can change the name and the folder in the dialog. Leathercase writes that one file and nothing else.</p><h2 id="what-leaves-and-what-stays" tabindex="-1">What leaves and what stays <a class="header-anchor" href="#what-leaves-and-what-stays" aria-label="Permalink to &quot;What leaves and what stays&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goes into the export</th><th>Stays behind</th></tr></thead><tbody><tr><td>Every note of the manuscript, in the order the manuscript view shows</td><td>Notes about characters, places and other world notes</td></tr><tr><td>Your italics and bold</td><td>Your <code>%% comments %%</code> and Leathercase&#39;s comments</td></tr><tr><td>Scene breaks, from headings inside a chapter and horizontal rules</td><td>Links&#39; targets (only their text goes)</td></tr><tr><td>Part pages, when <strong>Parts</strong> is on</td><td>Thread anchors, lenses and anything Leathercase keeps in its own files</td></tr></tbody></table><p>Highlights go along as plain text in Word, PDF and EPUB, and as highlights in Markdown.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/manuscript">Manuscript</a></li><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/reference/settings">Settings</a></li><li><a href="/guide/reference/languages">Languages</a></li><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/keys">Keys and commands</a></li></ul>',22))])}const y=a(d,[["render",l]]);export{f as __pageData,y as default};
